using UdonSharp;
using UnityEngine;

namespace NovaOS.FNF
{
    /// <summary>
    /// Flattened chart data arrays generated by the Editor chart importer.
    /// This layout avoids generic collections and jagged arrays in Udon runtime.
    /// </summary>
    public class NovaFNFChartBank : UdonSharpBehaviour
    {
        [Header("One entry per song / variation / difficulty")]
        public string[] chartKeys;
        public string[] songIds;
        public string[] variationIds;
        public string[] difficultyIds;
        public string[] songNames;
        public string[] artists;
        public float[] baseBpms;
        public float[] scrollSpeeds;
        public int[] noteStarts;
        public int[] noteCounts;
        public int[] bpmStarts;
        public int[] bpmCounts;

        [Header("Flattened note arrays")]
        public float[] noteTimesMs;
        public int[] noteDirections;
        public float[] sustainLengthsMs;
        public string[] noteKinds;

        [Header("Flattened BPM change arrays")]
        public float[] bpmChangeTimesMs;
        public float[] bpmValues;

        public int FindChartIndex(string songId, string difficultyId)
        {
            string wantedSong = NormalizeId(songId);
            string wantedDifficulty = NormalizeId(difficultyId);
            if (chartKeys == null) return -1;

            for (int i = 0; i < chartKeys.Length; i++)
            {
                if (i >= songIds.Length || i >= difficultyIds.Length) break;
                if (NormalizeId(songIds[i]) == wantedSong &&
                    NormalizeId(difficultyIds[i]) == wantedDifficulty)
                    return i;
            }
            return -1;
        }

        public int FindFirstDifficulty(string songId)
        {
            string wantedSong = NormalizeId(songId);
            if (songIds == null) return -1;
            for (int i = 0; i < songIds.Length; i++)
                if (NormalizeId(songIds[i]) == wantedSong) return i;
            return -1;
        }

        private string NormalizeId(string value)
        {
            if (string.IsNullOrEmpty(value)) return "";
            return value.Trim().ToLowerInvariant().Replace("_", "-").Replace(" ", "-");
        }
    }
}
